from typing import List


def teamFormation(lowerSkill: List[int], higherSkill: List[int]) -> int:
    n = len(lowerSkill)

    def can(k: int) -> bool:
        cnt = 0
        for i in range(n):
            if cnt <= lowerSkill[i] and k - 1 - cnt <= higherSkill[i]:
                cnt += 1
                if cnt == k:
                    return True
        return False

    lo, hi = 0, n
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if can(mid):
            lo = mid
        else:
            hi = mid - 1
    return lo
